import{_ as o,o as s,c as r,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Month 2021: Dashboard Update","description":"","frontmatter":{"title":"Ceph Month 2021: Dashboard Update","date":"2021-06-15T00:00:00.000Z","updated":"2021-06-16T00:00:00.000Z","tags":["Ceph","Dashboard","Pacific 版本","Quincy 版本","Orchestration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_Dashboard_Update.md","filePath":"posts/2021/Ceph_Month_2021_-_Dashboard_Update.md","lastUpdated":1780459816000}'),n={name:"posts/2021/Ceph_Month_2021_-_Dashboard_Update.md"};function e(i,t,l,p,_,d){return s(),r("div",null,[...t[0]||(t[0]=[a("<p>Ceph Dashboard 组件负责人 Ernesto Puerta 在 Ceph Month 2021 会议中介绍了 Dashboard 的最新更新和未来规划。以下是会议的关键点：</p><ol><li><p><strong>Pacific 版本亮点</strong>：</p><ul><li><strong>Cepheum 集成</strong>：与 Orchestrator 的整合，主要集中在 Cepheum 上，Rook 的支持预计将在 Quincy 版本中完成。</li><li><strong>RGW 增强</strong>：支持高级工作流程，如多站点监控和多站点同步监控。</li><li><strong>RESTful API</strong>：Dashboard 的 API 正式化，并承诺保持 API 的稳定性。</li><li><strong>安全性改进</strong>：包括账户锁定、使用安全 cookies 存储敏感信息等。</li></ul></li><li><p><strong>Quincy 版本规划</strong>：</p><ul><li><strong>用户工作流程</strong>：提供更多高级用户工作流程，如集群安装向导。</li><li><strong>多站点与多集群支持</strong>：增强对多站点和多集群的支持，包括 RGW 镜像和 CephFS 镜像。</li><li><strong>RGW 高级工作流程</strong>：增加桶策略、生命周期管理、服务器端加密等功能。</li><li><strong>可观测性增强</strong>：考虑增加日志聚合功能，以改善日志管理。</li></ul></li><li><p><strong>性能与用户体验改进</strong>：</p><ul><li><strong>性能优化</strong>：讨论了关于 RBD 图像列表等性能问题，计划进行内部清理和重构以提高性能。</li><li><strong>用户体验</strong>：计划改进 Dashboard 的登录页面，使其对所有用户更加友好。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li><strong>社区参与</strong>：鼓励社区成员通过 IRC 频道和 GitHub 参与到 Dashboard 的开发中。</li><li><strong>技术分享</strong>：计划举办技术讲座，分享 Dashboard 的开发经验和代码走查。</li></ul></li></ol><p>会议确认了 Pacific 版本的主要更新和 Quincy 版本的发展方向，并确定了性能优化和用户体验改进的具体计划。</p>",3)])])}const c=o(n,[["render",e]]);export{g as __pageData,c as default};
